import sqlite3, math, itertools, unicodedata, collections, sys
from decimal import Decimal, getcontext
getcontext().prec=50
c=sqlite3.connect("file:/Volumes/ZT/repos/llc2026/ocean-above/locations.db?mode=ro",uri=True)
rows=c.execute("select city_name,coordinate,is_hub,connected_hubs from locations").fetchall()
links=c.execute("select hub_a,hub_b from hub_links").fetchall()
print("cities",len(rows),"hubs",sum(r[2] for r in rows),"links",len(links))
names={r[0] for r in rows}; hubs={r[0] for r in rows if r[2]}
coord={}
bad=[]
for n,co,h,ch in rows:
    try:
        x,y=co.split(","); coord[n]=(int(x),int(y))
        if co!=f"{int(x)},{int(y)}": bad.append(("fmt",n,co))
    except Exception as e: bad.append((n,co))
print("bad coords",bad[:10],len(bad))
# names oddities
print("names w/ whitespace edge",[n for n in names if n!=n.strip()])
print("non-ascii names",sorted(n for n in names if not n.isascii())[:40])
print("names with digits",[n for n in names if any(ch.isdigit() for ch in n)])
print("names with punctuation",sorted(n for n in names if any(not (ch.isalpha() or ch==' ') for ch in n))[:60])
def fold(s):
    s=unicodedata.normalize("NFKD",s); s="".join(ch for ch in s if not unicodedata.combining(ch)); return s.casefold().strip()
f=collections.defaultdict(list)
for n in names: f[fold(n)].append(n)
print("fold collisions",[v for v in f.values() if len(v)>1])
# connected hubs
noserv=[]; issues=[]
adj=collections.defaultdict(set)
for n,co,h,ch in rows:
    parts=[p for p in ch.split(";")] if ch else []
    if h and ch: issues.append(("hub with ch",n,ch))
    if not h and not ch: noserv.append(n)
    for p in parts:
        if p!=p.strip() or p=="" : issues.append(("ws/empty",n,repr(ch)))
        p2=p.strip()
        if p2 not in names: issues.append(("unknown hub",n,p))
        elif p2 not in hubs: issues.append(("non-hub ref",n,p))
        if p2 in names: adj[n].add(p2); adj[p2].add(n)
    if len(parts)!=len(set(parts)): issues.append(("dup",n,ch))
print("no service",len(noserv),noserv)
print("issues",issues[:20],len(issues))
li=[]
seen=set()
for a,b in links:
    if a not in hubs or b not in hubs: li.append(("nonhub link",a,b))
    if a==b: li.append(("self",a,b))
    if (b,a) in seen: li.append(("reverse dup",a,b))
    seen.add((a,b)); adj[a].add(b); adj[b].add(a)
print("link issues",li[:20],len(li))
hubdeg={h:len([x for x in adj[h] if x in hubs]) for h in hubs}
print("hubs w/o hub links",[h for h,d in hubdeg.items() if d==0])
# isolated hubs (no links at all)
print("hubs no edges at all",[h for h in hubs if not adj[h]])
# coordinate dupes
cc=collections.defaultdict(list)
for n,p in coord.items(): cc[p].append(n)
print("same coord",[v for v in cc.values() if len(v)>1])
xs=[p[0] for p in coord.values()]; ys=[p[1] for p in coord.values()]
print("range",min(xs),max(xs),min(ys),max(ys))
# hub graph connectivity
import heapq
def d(a,b):
    (x1,y1),(x2,y2)=coord[a],coord[b]; return Decimal((x1-x2)**2+(y1-y2)**2).sqrt()
comp={}
for h in hubs:
    if h in comp: continue
    st=[h]; comp[h]=h
    while st:
        u=st.pop()
        for v in adj[u]:
            if v in hubs and v not in comp: comp[v]=h; st.append(v)
print("hub components",collections.Counter(comp.values()))
# Floyd on hubs (float), count ties & direct-not-cheapest sanity
H=sorted(hubs); idx={h:i for i,h in enumerate(H)}
INF=float("inf"); D=[[INF]*len(H) for _ in H]
for h in H: D[idx[h]][idx[h]]=0.0
for a in H:
    for b in adj[a]:
        if b in hubs: D[idx[a]][idx[b]]=float(d(a,b))
for k in range(len(H)):
    for i in range(len(H)):
        for j in range(len(H)):
            if D[i][k]+D[k][j]<D[i][j]: D[i][j]=D[i][k]+D[k][j]
# nearest served ties; unserved -> nearest
served=[n for n in names if n in hubs and adj[n] or (n not in hubs and adj[n])]
print("served",len(served))
for n in noserv:
    ds=sorted((( (coord[n][0]-coord[s][0])**2+(coord[n][1]-coord[s][1])**2),s) for s in served)
    print(" ",n,coord[n],"->",ds[0],ds[1], "TIE" if ds[0][0]==ds[1][0] else "")
# nonhub pairs sharing connections: check whether two non-hub cities 'connected' issue; nonhub listing nonhub handled above
# zero-length legs
z=[(a,b) for a in names for b in adj[a] if coord[a]==coord[b]]
print("zero legs",z)
# perfect-square legs count (exact ints) & tie probability: count equal-cost alt hub pairs for sample
# hub named in connected_hubs that is isolated in hub graph
print("hub degree min",sorted(hubdeg.items(),key=lambda x:x[1])[:5])
print("nonhub conn count dist",collections.Counter(len(adj[n]) for n in names if n not in hubs))
EOF
